<section class="panel table-panel">
    <div class="table-toolbar"><div><h2>Workspace activity <span class="count-badge"><?= number_format(count($activities)) ?></span></h2><p>Most recent actions performed by your team</p></div><span class="role-note">Visible to administrators only</span></div>
    <?php if ($activities): ?><div class="table-scroll"><table class="data-table"><thead><tr><th>TEAM MEMBER</th><th>ACTION</th><th>RECORD</th><th>DETAILS</th><th>WHEN</th></tr></thead><tbody>
    <?php foreach ($activities as $activity): ?><tr><td><div class="table-person"><span class="table-avatar avatar-lilac"><?= e(mb_strtoupper(mb_substr($activity['user_name'], 0, 1))) ?></span><div><strong><?= e($activity['user_name']) ?></strong><span><?= e($activity['ip_address'] ?: 'Local session') ?></span></div></div></td><td><span class="activity-action"><?= e(ucfirst($activity['action'])) ?></span></td><td><?= e(ucfirst($activity['entity'])) ?><?= $activity['entity_id'] ? ' #' . (int) $activity['entity_id'] : '' ?></td><td class="activity-details"><?= e($activity['details'] ?: '—') ?></td><td><strong class="date-primary"><?= e(format_date($activity['created_at'])) ?></strong><span class="cell-sub"><?= e(date('g:i A', strtotime($activity['created_at']))) ?></span></td></tr><?php endforeach; ?>
    </tbody></table></div><?php else: ?><div class="empty-state"><span class="empty-icon">↗</span><strong>No activity recorded yet.</strong><p>Sign-ins and record updates will appear here.</p></div><?php endif; ?>
    <div class="table-footer">Showing the latest <?= number_format(count($activities)) ?> events. Activity records are retained for accountability.</div>
</section>
